/* ===========================================================================
   Aubry & Vent — Caliber 08
   A specimen sheet for a movement: warm drawing paper for the reading, one
   dark lit band where the mechanism is shown running. Gilt is reserved for
   energy and for allocation; nothing else on the page uses it.
   =========================================================================== */

:root {
  /* two temperatures: warm paper field, cool steel band */
  --paper: #f2eee5;
  --paper-2: #eae4d6;
  --paper-3: #e2dbca;
  --ink: #1b1a17;
  --ink-2: #57534b;
  --ink-3: #837c6f;
  --rule: #d2cbba;
  --rule-2: #c1b8a3;

  --dark: #15181b;
  --dark-2: #1d2226;
  --silver: #c4c9c7;
  --silver-2: #7d8586;

  --gilt: #a3762f;
  --gilt-lit: #e2a94e;

  --ease-out: cubic-bezier(.2, .8, .3, 1);
  --ease-in-out: cubic-bezier(.6, 0, .3, 1);
  --t-fast: 130ms;
  --t-base: 190ms;
  --t-slow: 340ms;

  --gut: clamp(20px, 5vw, 72px);
  --bar-h: 58px;

  --sans: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.62;
  font-feature-settings: 'kern' 1;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
svg { display: block; }

.num {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
  letter-spacing: -0.01em;
}

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* --- ambient layer ------------------------------------------------------- */

a, button, input, label.finish, .slab, .stage {
  transition:
    color var(--t-fast) var(--ease-out),
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    box-shadow var(--t-base) var(--ease-out),
    opacity var(--t-base) var(--ease-out),
    transform var(--t-base) var(--ease-out);
}

:where(a, button, input, summary):focus-visible,
label.finish:focus-within {
  outline: 2px solid var(--gilt);
  outline-offset: 3px;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity var(--t-slow) var(--ease-out), transform var(--t-slow) var(--ease-out);
}
[data-reveal].is-in { opacity: 1; transform: none; }
[data-reveal].is-instant { transition: none; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
  }
  [data-reveal] { opacity: 1; transform: none; }
}

/* --- shared -------------------------------------------------------------- */

h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 400;
  letter-spacing: -0.018em;
  line-height: 1.02;
  margin: 0;
}

p { margin: 0; }

.eyebrow {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.eyebrow__no {
  color: var(--ink);
  border-bottom: 1px solid var(--gilt);
  padding-bottom: 2px;
}

.band-head {
  padding: 0 var(--gut);
  max-width: 1500px;
  margin: 0 auto;
}
.band-head h2 {
  font-size: clamp(34px, 4.4vw, 60px);
  margin: 22px 0 0;
  max-width: 15ch;
}
.band-head__lede {
  margin-top: 18px;
  max-width: 46ch;
  color: var(--ink-2);
  font-size: 17px;
}
.band-head--dark { color: var(--silver); }
.band-head--dark .eyebrow { color: var(--silver-2); }
.band-head--dark .eyebrow__no { color: #fff; }
.band-head--dark .band-head__lede { color: #a7afb0; }

.btn {
  --btn-bg: var(--ink);
  --btn-fg: var(--paper);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--btn-bg);
  color: var(--btn-fg);
  border: 1px solid var(--btn-bg);
  border-radius: 2px;
  padding: 13px 22px;
  font-family: var(--mono);
  font-size: 12.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
}
.btn:hover { --btn-bg: #000; box-shadow: 0 3px 0 0 var(--gilt); transform: translateY(-1px); }
.btn:active { transform: translateY(0); box-shadow: 0 1px 0 0 var(--gilt); }
.btn:disabled { --btn-bg: var(--rule-2); --btn-fg: #f7f4ee; cursor: not-allowed; box-shadow: none; transform: none; border-color: var(--rule-2); }
.btn--quiet { --btn-bg: transparent; --btn-fg: var(--ink); border-color: var(--rule-2); }
.btn--quiet:hover { --btn-bg: var(--paper-3); box-shadow: 0 3px 0 0 var(--rule-2); }

/* --- title bar ----------------------------------------------------------- */

.bar {
  position: sticky;
  top: 0;
  z-index: 40;
  height: var(--bar-h);
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 var(--gut);
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--rule);
}
.bar__mark {
  display: flex;
  align-items: baseline;
  gap: 12px;
  text-decoration: none;
  color: var(--ink);
  margin-right: auto;
}
.bar__house { font-family: var(--serif); font-size: 21px; letter-spacing: -0.01em; }
.bar__ref { font-size: 11px; color: var(--ink-3); letter-spacing: 0.06em; }
.bar__mark:hover .bar__ref { color: var(--gilt); }

.bar__nav { display: flex; gap: 26px; }
.bar__nav a {
  font-size: 13px;
  color: var(--ink-2);
  text-decoration: none;
  padding: 4px 0;
  border-bottom: 1px solid transparent;
}
.bar__nav a:hover { color: var(--ink); border-bottom-color: var(--gilt); }

.bar__cta {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 2px;
  padding: 8px 14px;
}
.bar__cta:hover { background: var(--ink); color: var(--paper); }
.bar__left { color: var(--gilt); font-size: 11px; letter-spacing: 0.02em; }
.bar__cta:hover .bar__left { color: var(--gilt-lit); }

/* --- hero ---------------------------------------------------------------- */

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 1fr);
  grid-template-areas: 'type plate' 'block plate';
  align-items: start;
  gap: 0 clamp(24px, 4vw, 64px);
  padding: clamp(48px, 7vw, 92px) var(--gut) clamp(40px, 5vw, 64px);
  max-width: 1500px;
  margin: 0 auto;
}

.hero__type { grid-area: type; max-width: 30ch; }

.hero h1 {
  font-size: clamp(64px, 11vw, 156px);
  line-height: 0.86;
  margin: 26px 0 0;
  letter-spacing: -0.035em;
}
.hero__num {
  display: block;
  color: var(--gilt);
  font-variant-numeric: lining-nums;
}

.hero__lede {
  margin-top: 26px;
  font-size: clamp(19px, 1.5vw, 22px);
  line-height: 1.42;
  max-width: 26ch;
}
.hero__claim {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 16px;
  max-width: 40ch;
  padding-top: 18px;
  border-top: 1px solid var(--rule);
}
.hero__actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }

.hero__plate {
  grid-area: plate;
  position: relative;
  align-self: center;
  background:
    linear-gradient(transparent 39px, rgba(27, 26, 23, .045) 39px),
    linear-gradient(90deg, transparent 39px, rgba(27, 26, 23, .045) 39px);
  background-size: 40px 40px;
  border: 1px solid var(--rule);
  border-radius: 3px;
  padding: clamp(10px, 2vw, 26px);
}

.hero__block {
  grid-area: block;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 46px 0 0;
  border-top: 1px solid var(--ink);
}
.hero__block > div {
  padding: 12px 12px 12px 0;
  border-bottom: 1px solid var(--rule);
}
.hero__block dt {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.hero__block dd { margin: 4px 0 0; font-size: 15px; }

/* the plate outline drawing */
.outline { width: 100%; height: auto; }
.outline__plate { fill: var(--paper-2); stroke: var(--ink); stroke-width: 2; }
.outline__hair { fill: none; stroke: var(--rule-2); stroke-width: 1; }
.outline__ghost circle { fill: none; stroke: var(--rule-2); stroke-width: 1; stroke-dasharray: 3 4; }
.outline__jewels circle { fill: #9a3c33; opacity: .85; }
.outline__marks line { stroke: var(--ink-3); stroke-width: .8; stroke-dasharray: 12 4 2 4; }
.outline__dim line, .outline__dim path { stroke: var(--ink-2); stroke-width: 1; fill: none; }
.outline__dim text, .outline__side text {
  font-family: var(--mono); font-size: 15px; fill: var(--ink-2); letter-spacing: .02em;
}
.outline__side rect { fill: var(--ink); }
.outline__side line { stroke: var(--ink-2); stroke-width: 1; }

/* --- the power path: the lit band ---------------------------------------- */

.path {
  background: var(--dark);
  color: var(--silver);
  padding: clamp(64px, 8vw, 112px) 0 clamp(72px, 9vw, 128px);
  position: relative;
}
.path::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 70% 60% at 32% 42%, rgba(226, 169, 78, .07), transparent 70%);
  pointer-events: none;
}

.path__grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 72px);
  max-width: 1500px;
  margin: 0 auto;
  padding: 0 var(--gut);
}

.path__stagewrap { position: relative; }
.path__plan {
  position: sticky;
  top: calc(var(--bar-h) + 24px);
  padding: 8px 0 0;
}
.plan { width: 100%; height: auto; max-height: calc(100vh - var(--bar-h) - 90px); }

.path__counter {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-family: var(--mono);
  margin-top: 4px;
  padding-left: 4px;
}
.path__counter-no { font-size: 26px; color: var(--gilt-lit); }
.path__counter-of { font-size: 12px; color: var(--silver-2); letter-spacing: .1em; }

/* schematic */
.plan__plate circle { fill: #191d21; stroke: #333a3e; stroke-width: 1.5; }
.plan__plate .plan__hair { fill: none; stroke: #262c30; }
.plan__marks line { stroke: #2c3337; stroke-width: .8; stroke-dasharray: 14 5 2 5; }

.plan__part { transition: opacity var(--t-base) var(--ease-out); opacity: .42; }
.plan__part.is-lit { opacity: 1; }
.plan__rim { fill: none; stroke: var(--silver); stroke-width: 1.4; }
.plan__part .plan__hair { fill: none; stroke: #4d5557; stroke-width: 1; }
.plan__teeth line { stroke: var(--silver-2); stroke-width: 1.1; }
.plan__spokes line { stroke: #6f7778; stroke-width: 1.1; }
.plan__weight { fill: #2a3033; stroke: var(--silver-2); stroke-width: 1; }
.plan__pivot { fill: var(--silver); }
.plan__fork path { fill: none; stroke: var(--silver); stroke-width: 1.4; stroke-linejoin: round; }
.plan__stopwork { fill: none; stroke: var(--silver-2); stroke-width: 1.2; }
.plan__hands { fill: none; stroke: var(--silver); stroke-width: 2; stroke-linecap: round; }
.plan__spring, .plan__hairspring { fill: none; stroke: #495052; stroke-width: 1; }
.plan__jewels circle { fill: #8e392f; opacity: .55; }

.plan__seg {
  fill: none;
  stroke: var(--gilt);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  opacity: .78;
  transition: stroke-dashoffset .62s var(--ease-out), stroke-width var(--t-base), opacity var(--t-base);
}
.plan__seg.is-drawn { stroke-dashoffset: 0; }
.plan__seg.is-active { stroke: var(--gilt-lit); stroke-width: 2.6; opacity: 1; }
.plan__seg--return { stroke-width: 1.2; opacity: .5; }
.plan__seg--return.is-active { stroke-width: 1.6; }

.plan__beat {
  fill: none;
  stroke: var(--gilt-lit);
  stroke-width: 1.5;
  transform-box: view-box;
  transform-origin: 250px 300px;
  animation: beat .4s linear infinite;
}
@keyframes beat {
  0%   { transform: scale(.72); opacity: .95; }
  100% { transform: scale(1.5);  opacity: 0; }
}

.plan__tag text {
  font-family: var(--mono);
  font-size: 15px;
  fill: #eef1f0;
  letter-spacing: .02em;
}
.plan__tag-fig { font-size: 13px !important; fill: var(--gilt-lit) !important; }
.plan__leader { fill: none; stroke: var(--gilt); stroke-width: 1; stroke-dasharray: 3 3; }
.plan__leader-dot { fill: var(--gilt-lit); }

/* stage list */
.path__list { list-style: none; margin: 0; padding: 0; }

.stage {
  padding: 30px 0 30px 26px;
  min-height: 40vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid #2b3236;
  border-top: 1px solid #23292d;
  outline-offset: -2px;
  opacity: .45;
}
.stage:first-child { border-top: none; }
.stage.is-active { opacity: 1; border-left-color: var(--gilt); }
.stage.is-past { opacity: .62; border-left-color: #5a4322; }
.stage:hover { opacity: 1; }

.stage__figure { display: flex; flex-direction: column; gap: 2px; }
.stage__lead {
  font-family: var(--mono);
  font-size: clamp(30px, 3.4vw, 46px);
  line-height: 1;
  color: var(--gilt-lit);
  letter-spacing: -0.03em;
}
.stage.is-active .stage__lead { color: var(--gilt-lit); }
.stage:not(.is-active) .stage__lead { color: #8d7c5f; }
.stage__unit {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--silver-2);
}

.stage__name {
  font-size: clamp(24px, 2.2vw, 31px);
  margin-top: 18px;
  color: #f0f2f1;
  display: flex;
  align-items: baseline;
  gap: 14px;
}
.stage__no {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--silver-2);
  letter-spacing: .06em;
}
.stage__detail {
  margin-top: 12px;
  max-width: 44ch;
  color: #b4bbbb;
  font-size: 16px;
}
.stage__full {
  margin-top: 10px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: .04em;
  color: var(--silver-2);
}
.stage.is-active .stage__full { color: var(--gilt); }

/* --- construction -------------------------------------------------------- */

.layers { padding: clamp(64px, 8vw, 112px) 0; }

.layers__body {
  max-width: 1500px;
  margin: 52px auto 0;
  padding: 0 var(--gut);
  display: grid;
  grid-template-columns: minmax(340px, 0.95fr) minmax(0, 1fr);
  gap: clamp(28px, 5vw, 80px);
  align-items: center;
}

.layers__stack { position: relative; }
.layers__edge {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-3);
  padding: 6px 0;
}
.layers__slabs { position: relative; border-left: 1px solid var(--rule); }

.slab {
  display: grid;
  grid-template-columns: 56px 1fr auto;
  align-items: center;
  gap: 16px;
  width: 100%;
  height: calc(var(--mm) * 46px);
  min-height: 32px;
  padding: 0 16px 0 0;
  background: var(--paper-2);
  border: 0;
  border-top: 1px solid var(--rule-2);
  border-radius: 0 2px 2px 0;
  font: inherit;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.slab:first-child { border-top: 1px solid var(--ink); }
.slab:last-child { border-bottom: 1px solid var(--ink); }
.slab.is-open { transform: translateX(18px); background: var(--paper-3); box-shadow: -3px 0 0 0 var(--gilt); }

.slab__face { display: block; height: 100%; width: 56px; }
[data-layer='dial-side'] .slab__face { background: repeating-linear-gradient(90deg, #cfc7b4 0 2px, #ded7c6 2px 5px); }
[data-layer='main'] .slab__face {
  background:
    radial-gradient(circle at 3px 3px, rgba(0,0,0,.14) 1px, transparent 1.6px) 0 0/7px 7px,
    #d6cfbd;
}
[data-layer='bridge'] .slab__face { background: linear-gradient(100deg, #2a2b2c 0 42%, #b9bdbb 48%, #2a2b2c 54% 100%); }
[data-layer='balance-cock'] .slab__face { background: repeating-linear-gradient(115deg, #c9c1ae 0 3px, #e0d9c8 3px 7px); }

.slab__name { font-size: 15px; }
.slab__mm { font-size: 13px; color: var(--ink-2); }

.layers__dim {
  position: absolute;
  right: -34px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--ink-2);
}
.layers__dim::before, .layers__dim::after {
  content: '';
  position: absolute; left: -5px; width: 11px; height: 1px; background: var(--ink-2);
}
.layers__dim::before { top: 0; }
.layers__dim::after { bottom: 0; }
.layers__dim-value {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 13px;
  color: var(--ink-2);
  white-space: nowrap;
}

.layers__notes { display: flex; flex-direction: column; gap: 2px; }
.layers__note {
  padding: 15px 18px;
  border-left: 2px solid transparent;
  color: var(--ink-2);
  font-size: 15.5px;
  max-width: 54ch;
  transition: background-color var(--t-fast) var(--ease-out), border-color var(--t-fast) var(--ease-out), color var(--t-fast) var(--ease-out);
}
.layers__note.is-open { background: var(--paper-2); border-left-color: var(--gilt); color: var(--ink); }
.layers__note-name { display: block; color: var(--ink); font-size: 13px; letter-spacing: .01em; margin-bottom: 3px; }
.layers__note-name .num { color: var(--ink-3); font-size: 12px; margin-left: 6px; }

/* --- specification: the rest --------------------------------------------- */

.spec {
  background: var(--paper-2);
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  padding: clamp(56px, 7vw, 96px) 0;
}
.spec__inner {
  max-width: 1500px;
  margin: 0 auto;
  padding: 0 var(--gut);
  display: grid;
  grid-template-columns: minmax(220px, 0.6fr) minmax(0, 1.4fr);
  gap: clamp(24px, 4vw, 72px);
  align-items: start;
}
.spec__head h2 { font-size: clamp(30px, 3.4vw, 46px); margin-top: 20px; }
.spec__note { margin-top: 14px; font-size: 14px; color: var(--ink-3); max-width: 26ch; }

.spec__list {
  margin: 0;
  columns: 2;
  column-gap: clamp(28px, 4vw, 72px);
}
.spec__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 11px 0;
  border-bottom: 1px solid var(--rule);
  break-inside: avoid;
}
.spec__row:first-child { border-top: 1px solid var(--ink); }
.spec__row dt {
  font-size: 14px;
  color: var(--ink-2);
  white-space: nowrap;
}
.spec__row dd { margin: 0; font-size: 14.5px; text-align: right; }

/* --- workshop ------------------------------------------------------------ */

.shop { padding: clamp(64px, 8vw, 112px) 0 clamp(56px, 7vw, 96px); }

.shop__figure {
  margin: 44px 0 0;
  position: relative;
}
.shop__figure img {
  width: 100%;
  height: clamp(240px, 38vw, 420px);
  object-fit: cover;
  object-position: 50% 62%;
  filter: grayscale(.72) contrast(1.04) brightness(.96) sepia(.14);
}
.shop__figure figcaption {
  max-width: 1500px;
  margin: 10px auto 0;
  padding: 0 var(--gut);
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .06em;
  color: var(--ink-3);
  text-transform: uppercase;
}

.shop__facts {
  list-style: none;
  max-width: 1500px;
  margin: clamp(36px, 4vw, 60px) auto 0;
  padding: 0 var(--gut);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 0 clamp(24px, 3vw, 56px);
}
.shop__facts li {
  display: grid;
  grid-template-columns: 30px 1fr;
  grid-template-areas: 'mark label' '. body';
  gap: 4px 10px;
  padding: 22px 0;
  border-top: 1px solid var(--rule);
  align-content: start;
}
.shop__facts li:first-child { border-top-color: var(--ink); }
.shop__mark {
  grid-area: mark;
  color: var(--gilt);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 26px;
  border-left: 1px solid var(--rule-2);
}
.shop__label {
  grid-area: label;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-3);
  align-self: center;
}
.shop__facts p { grid-area: body; margin-top: 6px; font-size: 15.5px; color: var(--ink-2); }

/* the third fact is the one that bounds the whole page: give it weight */
.shop__facts li:nth-child(3) p { color: var(--ink); font-size: 17px; }

/* --- reserve ------------------------------------------------------------- */

.reserve {
  background: var(--paper-2);
  border-top: 1px solid var(--rule);
  padding: clamp(64px, 8vw, 112px) 0 clamp(72px, 8vw, 112px);
}

.alloc {
  max-width: 1500px;
  margin: 44px auto 0;
  padding: 0 var(--gut);
}
.alloc__ticks {
  display: grid;
  grid-template-columns: repeat(50, 1fr);
  gap: 4px 3px;
}
.alloc__tick {
  height: 14px;
  background: var(--rule-2);
  transition: background-color var(--t-base) var(--ease-out), transform var(--t-base) var(--ease-out);
}
.alloc__tick.is-free { background: var(--gilt); opacity: .5; }
.alloc__ticks.is-filtered .alloc__tick.is-free { opacity: .26; }
.alloc__tick.is-picked { opacity: 1; background: var(--gilt); transform: scaleY(1.4); }
.alloc__caption {
  margin-top: 14px;
  font-size: 14.5px;
  color: var(--ink-2);
}
.alloc__big { font-size: 19px; color: var(--ink); }

.reserve__form { max-width: 1500px; margin: 0 auto; padding: 0 var(--gut); }

.finishes { border: 0; margin: clamp(36px, 4vw, 56px) 0 0; padding: 0; }
.finishes__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(268px, 1fr));
  gap: 16px;
}

.finish {
  position: relative;
  display: grid;
  grid-template-columns: 60px 1fr;
  grid-template-areas: 'swatch name' 'swatch price' 'text text' 'meta meta';
  align-content: start;
  gap: 4px 16px;
  padding: 20px;
  background: var(--paper);
  border: 1px solid var(--rule-2);
  border-radius: 4px;
  cursor: pointer;
}
.finish:hover { border-color: var(--ink-3); transform: translateY(-2px); box-shadow: 0 6px 20px -12px rgba(27, 26, 23, .5); }
.finish.is-chosen {
  border-color: var(--gilt);
  box-shadow: inset 0 0 0 1px var(--gilt);
  background: #f6f2e9;
}
.finish input {
  position: absolute;
  opacity: 0;
  width: 1px; height: 1px;
  margin: 0;
}
.finish__swatch { grid-area: swatch; }
.swatch { width: 60px; height: 60px; border-radius: 2px; }
.swatch__ground { fill: #cfc8b6; }
.swatch--frosted circle { fill: #8f887a; opacity: .55; }
.swatch--skeleton .swatch__body { fill: #cfc8b6; stroke: #8f887a; stroke-width: 1.2; }
.swatch--skeleton .swatch__cut { fill: var(--paper); stroke: #8f887a; stroke-width: 1; }
.swatch--skeleton .swatch__angle { stroke: #fff; stroke-width: 1.6; fill: none; }

.finish__name { grid-area: name; font-family: var(--serif); font-size: 24px; line-height: 1.1; align-self: end; }
.finish__price { grid-area: price; font-size: 17px; color: var(--ink); align-self: start; }
.finish.is-chosen .finish__price { color: var(--gilt); }
.finish__finish { grid-area: text; margin-top: 14px; font-size: 14.5px; color: var(--ink-2); }
.finish__meta {
  grid-area: meta;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--rule);
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 13px;
  color: var(--ink-2);
}
.finish__left { font-size: 12px; color: var(--ink-3); }
.finish.is-chosen .finish__left { color: var(--gilt); }

.reserve__panel {
  margin-top: 20px;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 64px);
  align-items: start;
  background: var(--paper);
  border: 1px solid var(--rule-2);
  border-radius: 4px;
  padding: clamp(24px, 3vw, 40px);
}
.reserve__title { font-family: var(--serif); font-size: 30px; margin-bottom: 20px; }
.reserve__fields { display: flex; flex-direction: column; }

.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; max-width: 420px; }
.field label {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.field input {
  font: inherit;
  font-size: 16px;
  padding: 11px 13px;
  background: var(--paper-2);
  border: 1px solid var(--rule-2);
  border-radius: 2px;
  color: var(--ink);
}
.field input:hover { border-color: var(--ink-3); }
.field input:focus { outline: none; border-color: var(--gilt); box-shadow: inset 0 -2px 0 0 var(--gilt); background: var(--paper); }

.reserve__fields .btn { align-self: flex-start; margin-top: 6px; }
.reserve__hint { margin-top: 14px; font-size: 13.5px; color: var(--ink-2); font-family: var(--mono); }

.reserve__terms {
  align-self: end;
  font-size: 14.5px;
  color: var(--ink-2);
  border-left: 2px solid var(--gilt);
  padding-left: 18px;
  max-width: 40ch;
}

.record {
  max-width: 1500px;
  margin: clamp(36px, 4vw, 56px) auto 0;
  padding: clamp(28px, 3vw, 44px);
  background: var(--paper);
  border: 1px solid var(--gilt);
  border-radius: 4px;
  width: calc(100% - var(--gut) * 2);
}
.record__stamp {
  display: inline-block;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--gilt);
  border: 1px solid var(--gilt);
  border-radius: 2px;
  padding: 5px 12px;
}
.record__lede {
  font-family: var(--serif);
  font-size: clamp(24px, 2.6vw, 34px);
  line-height: 1.18;
  margin-top: 20px;
  max-width: 28ch;
}
.record__rows {
  margin: 30px 0 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 0 32px;
  border-top: 1px solid var(--ink);
}
.record__rows > div { padding: 12px 0; border-bottom: 1px solid var(--rule); }
.record__rows dt {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.record__rows dd { margin: 4px 0 0; font-size: 15.5px; overflow-wrap: anywhere; }
.record__note { margin-top: 24px; font-size: 14.5px; color: var(--ink-2); max-width: 56ch; }

/* --- footer -------------------------------------------------------------- */

.foot {
  background: var(--dark);
  color: var(--silver);
  padding: clamp(44px, 5vw, 72px) 0 clamp(32px, 4vw, 52px);
}
.foot__inner {
  max-width: 1500px;
  margin: 0 auto;
  padding: 0 var(--gut);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: baseline;
  gap: 20px clamp(24px, 4vw, 64px);
}
.foot__house { font-family: var(--serif); font-size: 30px; color: #eef1f0; }
.foot__links { list-style: none; margin: 0; padding: 0; display: flex; gap: 24px; }
.foot__links a, .foot__mail a { color: var(--silver); text-decoration: none; border-bottom: 1px solid transparent; }
.foot__links a:hover, .foot__mail a:hover { color: var(--gilt-lit); border-bottom-color: var(--gilt); }
.foot__links a, .foot__mail { font-size: 14px; }
.foot__mail { color: var(--silver-2); }
.foot__legal {
  grid-column: 1 / -1;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid #262c30;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .06em;
  color: var(--silver-2);
}

/* --- 1040px and below ---------------------------------------------------- */

@media (max-width: 1040px) {
  .hero {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: 'type' 'plate' 'block';
  }
  .hero__type { max-width: none; }
  .hero__plate { margin-top: 36px; max-width: 520px; }
  .hero__block { margin-top: 36px; }

  .path__grid { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .path__plan {
    top: var(--bar-h);
    background: var(--dark);
    padding: 10px 0 12px;
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: end;
    gap: 12px;
    border-bottom: 1px solid #262c30;
    z-index: 5;
  }
  .plan { max-height: 40vh; margin: 0 auto; }
  .path__counter { margin: 0 0 6px; }

  .stage { min-height: 0; padding: 26px 0 26px 20px; }

  .layers__body { grid-template-columns: minmax(0, 1fr); }
  .layers__dim { right: -30px; }

  .spec__inner { grid-template-columns: minmax(0, 1fr); }
  .spec__list { columns: 1; }
  .spec__head h2 { margin-top: 14px; }

  .reserve__panel { grid-template-columns: minmax(0, 1fr); }
  .reserve__terms { align-self: start; }

  .foot__inner { grid-template-columns: minmax(0, 1fr); }
}

/* --- 640px and below ----------------------------------------------------- */

@media (max-width: 640px) {
  body { font-size: 15.5px; }

  .bar { gap: 12px; }
  .bar__nav { display: none; }
  .bar__house { font-size: 18px; }
  .bar__cta { padding: 7px 11px; font-size: 11px; gap: 7px; }

  .hero { padding-top: 34px; }
  .hero h1 { font-size: clamp(58px, 20vw, 92px); }
  .hero__actions .btn { flex: 1 1 100%; justify-content: center; }
  .hero__block { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hero__plate { padding: 8px; background-size: 28px 28px; }

  .plan { max-height: 34vh; }
  .path__counter-no { font-size: 20px; }
  .stage__name { font-size: 22px; }
  .stage__detail { font-size: 15.5px; }

  /* the slab stack keeps its true proportions but needs more room per row */
  .slab { grid-template-columns: 44px 1fr auto; height: calc(var(--mm) * 40px); min-height: 40px; gap: 12px; }
  .slab__face { width: 44px; }
  .slab__name { font-size: 14px; }
  .layers__dim { display: none; }
  .layers__notes { margin-top: 26px; }
  .layers__note { padding: 13px 14px; }

  .alloc__ticks { grid-template-columns: repeat(25, 1fr); gap: 3px 2px; }
  .alloc__tick { height: 10px; }

  .finishes__grid { grid-template-columns: minmax(0, 1fr); }
  .finish { grid-template-columns: 48px 1fr; padding: 16px; }
  .swatch { width: 48px; height: 48px; }
  .finish__name { font-size: 21px; }

  .reserve__panel { padding: 20px; }
  .reserve__title { font-size: 25px; }
  .reserve__fields .btn { align-self: stretch; justify-content: center; }
  .field { max-width: none; }

  .shop__facts { grid-template-columns: minmax(0, 1fr); }
  .foot__links { flex-wrap: wrap; gap: 12px 20px; }
}

@media (max-width: 360px) {
  .hero__block { grid-template-columns: minmax(0, 1fr); }
  .alloc__ticks { grid-template-columns: repeat(20, 1fr); }
}

