import { chromium } from 'playwright'
const url = process.argv[2] || 'http://localhost:4173/'
const tag = process.argv[3] || 'a'
const b = await chromium.launch()
const errs = []
for (const [name, vp] of [['desktop',{width:1440,height:900}],['mobile',{width:390,height:844}]]) {
  const ctx = await b.newContext({ viewport: vp, deviceScaleFactor: 1 })
  const p = await ctx.newPage()
  p.on('console', m => { if (m.type()==='error') errs.push(name+': '+m.text()) })
  p.on('pageerror', e => errs.push(name+' pageerror: '+e.message))
  await p.goto(url, { waitUntil: 'networkidle' })
  await p.waitForTimeout(900)
  await p.screenshot({ path: `${process.env.HOME}/dvwork/shots/${tag}-${name}-top.png` })
  const h = await p.evaluate(() => document.documentElement.scrollHeight)
  const ow = await p.evaluate(() => document.documentElement.scrollWidth > window.innerWidth ? document.documentElement.scrollWidth : 0)
  // stitched sectional captures so sticky scenes are truthful
  const n = Math.min(9, Math.ceil(h / vp.height))
  for (let i = 0; i < n; i++) {
    await p.evaluate(y => window.scrollTo(0, y), i * vp.height)
    await p.waitForTimeout(700)
    await p.screenshot({ path: `${process.env.HOME}/dvwork/shots/${tag}-${name}-${String(i).padStart(2,'0')}.png` })
  }
  console.log(name, 'height', h, 'overflowWidth', ow, 'frames', n)
  await ctx.close()
}
console.log(errs.length ? 'CONSOLE:\n' + errs.join('\n') : 'console clean')
await b.close()
