await p.goto('http://localhost:4173/', { waitUntil:'networkidle' })
const dh = await p.evaluate(()=>document.documentElement.scrollHeight)
const vh = 900
const regions = await p.evaluate(()=>Array.from(document.querySelectorAll('main > *, main section, main header'))
  .filter(e=>e.getBoundingClientRect().height>80).slice(0,24)
  .map((e,i)=>{e.dataset.dreativeMotionId='m'+i;return {id:'m'+i,name:e.className.split(/\s+/)[0]}}))
const sig = sel => p.locator(sel).evaluate(root=>{
  const rr=root.getBoundingClientRect()
  return Array.from(root.querySelectorAll('*')).slice(0,40).map(el=>{
    const r=el.getBoundingClientRect(); const s=getComputedStyle(el)
    return JSON.stringify([Math.round(r.x-rr.x),Math.round(r.y-rr.y),Math.round(r.width),Math.round(r.height),s.transform,s.opacity,s.filter,s.clipPath,s.backgroundImage,s.color,s.backgroundColor])
  })
})
for (const rg of regions) {
  const sel = `[data-dreative-motion-id="${rg.id}"]`
  const top = await p.locator(sel).evaluate(e=>e.getBoundingClientRect().top+scrollY)
  const states=[]
  for (const off of [vh*.9, vh*.3, -vh*.35]) {
    const y=Math.max(0,Math.min(dh-vh, top-off))
    await p.evaluate(v=>scrollTo(0,v), y); await p.waitForTimeout(300)
    states.push((await sig(sel)).join('|'))
  }
  console.log(rg.name, 'distinct:', new Set(states).size)
}
await b.close()
